evidence.quote:
},
{
  "sinceChapter": 41,
  "untilChapter": 44,
  "value": "林能比较青玄编号与程记货号，仍只是关联待核。",
  "cause": "233日苏信实际送到，41当面展示；44唐带夹尚未启读比号。",
  "cost": "相似格式不证明同批、赵已收报告或指使行动。"
},
{
  "sinceChapter": 45,
  "untilChapter": 50,
  "value": "林掌握同号追链线索，与赵的责任关系仍未证实。",
  "cause": "246半联旧封与苏信比号；林只获当面证据，不知道程日后寄报及赵回令。",
  "cost": "验印、套号和原账仍待查，不能由运输关联升级为赵知情。"
},
{
  "sinceChapter": 51,
  "untilChapter": 52,
  "value": "林沿港口证据追查，赵尚未收到本港新报。",
  "cause": "52章258日程才交商驿封袋；报件尚在普通海陆路上。",
  "cost": "林不知道寄报；赵不能据未到消息遥控火场或追查。"
},
{
  "sinceChapter": 53,
  "untilChapter": 72,
  "value": "赵根据程的外港自述要求毁散账、保封匣；林仍只据当面材料追链。",
  "cause": "53章262赵阅第一报、263签回令、268程实收。赵仅知自己发令，不因程签收就即时得到回执。",
  "cost": "第一报只有254日前后程所见和自述，不含291北境失败。林苏未见报件和回令。"
},
{
  "sinceChapter": 73,
  "untilChapter": 79,
  "value": "赵面对程的北境损失自述与抵押物，林苏在返乡交证后继续独立核查。",
  "cause": "73章318程到乾都，当面交封匣原物及268回令签收联，述北境失败；72章林苏另已在315当面交材料。",
  "cost": "赵才据签收联确认旧回令到过程手；程的利己叙述不等于全貌，林苏不知道赵府此次面谈。"
},
{
  "sinceChapter": 80,
  "untilChapter": 87,
  "value": "赵主动把风险转向境内短途车队；林苏查证人和路线，尚无撤人令原件。",

{
  "stages": [
    {
      "sinceChapter": 15,
      "untilChapter": 17,
      "value": "拒绝越界资助，争取复核机会。",
      "cause": "15苏支持林拒交原件，放弃优先份额只换复核。",
      "cost": "停俸和路线限制继续，尚无古境许可。"
    },
    {
      "sinceChapter": 18,
      "untilChapter": 28,
      "value": "仅在本次任务许可内继续调查。",
      "cause": "18章180日实测后苏取得限定任务路线文书。",
      "cost": "优先份额不返还，不可任意进内门。"
    },
    {
      "sinceChapter": 29,
      "untilChapter": 32,
      "value": "留宗保护证人与监督押解。",
      "cause": "苏选择留下而非与林南渡，赵方须经消息往返才能反应。",
      "cost": "不得将后续被捕与反击提前视作事实。"
    },
    {
      "sinceChapter": 33,
      "untilChapter": 71,
      "value": "苏留宗护证并承受皇使和宗门压力，自己的原则不因林离开而改变。",
      "cause": "承接29留宗选择和12保留己方不利证词；41章那封226寄信只传已核的青玄近况。",
      "cost": "她没有获知赵与程后来来往的报令；保留原件不等于恢复职务。"
    },
    {
      "sinceChapter": 72,
      "untilChapter": 87,
      "value": "苏与归乡的林分工查本地车务，拒绝用受护者换外派资格。",
      "cause": "72章315面对面交证并决定先安置两名旧工友；后续亲查路单，保留自己曾签及韩改账原页。",
      "cost": "苏失去外派机会；赵并不自动知道她手里全部材料。"
    },
    {
      "sinceChapter": 88,
      "untilChapter": 94,
      "value": "苏准备救人并提交自己能证明的材料，尚未持有赵的撤人原令。",
      "cause": "88章431送案卷到当地监督点；90章433梁当面报告两车八人位置，苏与顾林据此分工。",
      "cost": "案卷不瞬时抵赵府，苏也不能由跟车推定433令文内容。"
    },
    {

